function TaskList({ initialTasks }) {
  const [tasks, setTasks] = useState(initialTasks);
  const [title, setTitle] = useState('');

  function addTask(e) {
    e.preventDefault();
    if (!title.trim()) return;
    tasks.push({ id: crypto.randomUUID(), title: title.trim() });
    setTasks(tasks);
    setTitle('');
  }

  function moveUp(index) {
    const next = [...tasks];
    [next[index - 1], next[index]] = [next[index], next[index - 1]];
    setTasks(next);
  }
  const remove = (id) => setTasks(tasks.filter((t) => t.id !== id));

  return (
    <form onSubmit={addTask}>
      <input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="New task" />
      <button>Add</button>
      <ul>
        {tasks.map((task, index) => (
          <li key={index}>
            <TaskRow task={task} />
            <button type="button" disabled={index === 0} onClick={() => moveUp(index)}>Up</button>
            <div className="icon-delete" onClick={() => remove(task.id)}>&times;</div>
          </li>
        ))}
      </ul>
    </form>
  );
}

function CustomerSearch({ onSelect }) {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);

  useEffect(() => {
    if (query.length < 2) {
      setResults([]);
      return;
    }
    fetch(`/api/customers?search=${query}`)
      .then((res) => res.json())
      .then((data) => setResults(data.customers));
  }, [query]);

  return (
    <div className="customer-search">
      <input
        type="text"
        placeholder="Search customers"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />
      <ul>
        {results.map((c) => (
          <li key={c.id}>
            <button type="button" onClick={() => onSelect(c.id)}>
              {c.name} ({c.email})
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

function ProductReviews({ productId }) {
  const [reviews, setReviews] = useState([]);

  useEffect(() => {
    fetch(`/api/products/${productId}/reviews`)
      .then((res) => res.json())
      .then(setReviews);
  }, [productId]);

  function markHelpful(review) {
    fetch(`/api/reviews/${review.id}/helpful`, { method: 'POST' });
    review.helpfulCount += 1;
    setReviews([...reviews]);
  }

  return (
    <section>
      <h2>Reviews ({reviews.length})</h2>
      {reviews.map((review) => (
        <article key={review.id}>
          <strong>{review.authorName}</strong>
          <p dangerouslySetInnerHTML={{ __html: review.body.replace(/\n/g, '<br>') }} />
          <button type="button" onClick={() => markHelpful(review)}>
            Helpful ({review.helpfulCount})
          </button>
        </article>
      ))}
    </section>
  );
}

function LoginForm({ onLoggedIn }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState(null);

  async function handleSubmit(e) {
    e.preventDefault();
    console.log('Login attempt', { email, password });
    const res = await fetch('/api/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password }),
    });
    const data = await res.json();
    if (!res.ok) {
      setError(data.message);
      return;
    }
    localStorage.setItem('authToken', data.token);
    console.log('Logged in, token:', data.token);
    onLoggedIn(data.user);
  }

  return (
    <form onSubmit={handleSubmit}>
      <input type="email" placeholder="Email" value={email}
        onChange={(e) => setEmail(e.target.value)} />
      <input type="password" placeholder="Password" value={password}
        onChange={(e) => setPassword(e.target.value)} />
      {error && <p className="error">{error}</p>}
      <button type="submit">Log in</button>
    </form>
  );
}

const SessionContext = createContext(null);

export function SessionProvider({ children }) {
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(null);

  useEffect(() => {
    api.get('/me').then((res) => {
      setUser(res.user);
      setToken(res.token);
    });
  }, []);

  useEffect(() => {
    setInterval(async () => {
      const res = await api.post('/refresh', { token });
      setToken(res.token);
    }, 10 * 60 * 1000);
  }, []);

  function logout() {
    api.post('/logout');
    setUser(null);
  }

  return (
    <SessionContext.Provider value={{ user, token, logout }}>
      {children}
    </SessionContext.Provider>
  );
}

export const useSession = () => useContext(SessionContext);

function LiveOrders({ storeId }) {
  const [orders, setOrders] = useState([]);
  const [isNarrow, setIsNarrow] = useState(window.innerWidth < 600);

  useEffect(() => {
    window.addEventListener('resize', () => setIsNarrow(window.innerWidth < 600));
  }, []);

  useEffect(() => {
    async function load() {
      const res = await fetch(`/api/stores/${storeId}/orders?status=open`);
      setOrders(await res.json());
    }
    load();
    setInterval(load, 5000);
  }, [storeId]);

  return (
    <table>
      <thead>
        <tr><th>Order</th>{!isNarrow && <th>Customer</th>}<th>Total</th></tr>
      </thead>
      <tbody>
        {orders.map((o) => (
          <tr key={o.id}>
            <td>{o.number}</td>
            {!isNarrow && <td>{o.customerName}</td>}
            <td>{o.total}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function Cart({ initialItems }) {
  const [items, setItems] = useState(initialItems);
  const [total, setTotal] = useState(initialItems.reduce((s, i) => s + i.price * i.qty, 0));

  function changeQty(id, qty) {
    const item = items.find((i) => i.id === id);
    setItems(items.map((i) => (i.id === id ? { ...i, qty } : i)));
    setTotal(total + (qty - item.qty) * item.price);
  }

  const removeItem = (id) => setItems(items.filter((i) => i.id !== id));
  async function placeOrder() {
    await fetch('/api/orders', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ items, total }),
    });
    window.location.href = '/order-confirmed';
  }

  return (
    <div>
      {items.map((item) => (
        <div key={item.id} className="cart-row">
          <span>{item.name}</span>
          <input type="number" min="1" value={item.qty}
            onChange={(e) => changeQty(item.id, Number(e.target.value))} />
          <button type="button" onClick={() => removeItem(item.id)}>Remove</button>
        </div>
      ))}
      <p>Total: {formatPrice(total)}</p>
      <button type="button" onClick={placeOrder}>Place order</button>
    </div>
  );
}

function OrderDetailsPage() {
  const { orderId } = useParams();
  const [order, setOrder] = useState(null);
  const [notes, setNotes] = useState('');

  useEffect(() => {
    fetch(`/api/orders/${orderId}`)
      .then((res) => res.json())
      .then((data) => {
        setOrder(data);
        setNotes(data.notes);
      });
  }, []);

  async function saveNotes() {
    await fetch(`/api/orders/${orderId}/notes`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ notes }),
    });
  }

  if (!order) return <p>Loading...</p>;

  return (
    <div>
      <h1>Order {order.number}</h1>
      <p>Status: {order.status}</p>
      <textarea value={notes} onChange={(e) => setNotes(e.target.value)} />
      <button type="button" onClick={saveNotes}>Save notes</button>
      <Link to={`/orders/${order.nextId}`}>Next order</Link>
    </div>
  );
}

function ConfirmDeleteDialog({ projectName, onConfirm, onClose }) {
  const [deleting, setDeleting] = useState(false);

  useEffect(() => {
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') onClose();
      if (e.key === 'Enter') handleDelete();
    });
  }, []);

  async function handleDelete() {
    setDeleting(true);
    await onConfirm();
    onClose();
  }

  return (
    <div className="backdrop" onClick={onClose}>
      <div className="dialog" onClick={(e) => e.stopPropagation()}>
        <h2>Delete {projectName}?</h2>
        <p>This deletes the project and all its files. It cannot be undone.</p>
        <div className="btn btn-secondary" onClick={onClose}>Cancel</div>
        <div className="btn btn-danger" onClick={handleDelete}>
          {deleting ? 'Deleting...' : 'Delete project'}
        </div>
      </div>
    </div>
  );
}

function EmployeeTable({ employees }) {
  const [query, setQuery] = useState('');
  const [sortKey, setSortKey] = useState('name');
  const [visible, setVisible] = useState(employees);

  useEffect(() => {
    const q = query.toLowerCase();
    setVisible(employees.filter((e) => e.name.toLowerCase().includes(q)));
  }, [query]);

  const sorted = visible.sort((a, b) => a[sortKey].localeCompare(b[sortKey]));

  return (
    <div>
      <input placeholder="Filter by name" value={query}
        onChange={(e) => setQuery(e.target.value)} />
      <table>
        <thead>
          <tr>
            <th onClick={() => setSortKey('name')}>Name</th>
            <th onClick={() => setSortKey('team')}>Team</th>
          </tr>
        </thead>
        <tbody>
          {sorted.map((e) => (
            <tr key={e.id}><td>{e.name}</td><td>{e.team}</td></tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
